PRAGMA foreign_keys = ON;
DROP VIEW IF EXISTS bias_context_profiles; DROP VIEW IF EXISTS premature_convergence_risks; DROP VIEW IF EXISTS idea_space_diversity_scores; DROP VIEW IF EXISTS frame_rotation_scores; DROP VIEW IF EXISTS assumption_challenge_priorities; DROP VIEW IF EXISTS stakeholder_visibility_scores; DROP VIEW IF EXISTS intervention_value_scores;
DROP TABLE IF EXISTS decision_memory; DROP TABLE IF EXISTS intervention_library; DROP TABLE IF EXISTS stakeholder_visibility; DROP TABLE IF EXISTS assumption_register; DROP TABLE IF EXISTS frame_rotation; DROP TABLE IF EXISTS idea_space_inventory; DROP TABLE IF EXISTS bias_contexts;
CREATE TABLE bias_contexts (context_id TEXT PRIMARY KEY, context_name TEXT, context_type TEXT, availability_pressure REAL, anchoring_intensity REAL, conformity_pressure REAL, framing_rigidity REAL, institutional_lock_in REAL, expert_enclosure REAL, ai_familiarity_pressure REAL, stakeholder_diversity REAL, exploratory_variation REAL, evidence_discipline REAL, political_safety REAL, decision_memory_quality REAL);
CREATE TABLE idea_space_inventory (idea_id TEXT PRIMARY KEY, context_id TEXT, idea_name TEXT, frame_family TEXT, mechanism_family TEXT, stakeholder_visibility REAL, novelty_level REAL, evidence_pathway REAL, strategic_relevance REAL, implementation_pathway REAL, system_level TEXT, source_diversity REAL, social_safety REAL, assumption_burden REAL);
CREATE TABLE frame_rotation (frame_id TEXT PRIMARY KEY, context_id TEXT, frame_name TEXT, frame_type TEXT, idea_count INTEGER, distinct_mechanisms INTEGER, stakeholder_inclusion REAL, system_level_coverage REAL, evidence_pathway_quality REAL, comfort_level REAL, frame_shift_value REAL);
CREATE TABLE assumption_register (assumption_id TEXT PRIMARY KEY, context_id TEXT, assumption_text TEXT, assumption_type TEXT, evidence_strength REAL, strategic_importance REAL, challenge_potential REAL, power_protection_risk REAL, stakeholder_burden_visibility REAL, revision_priority TEXT);
CREATE TABLE stakeholder_visibility (review_id TEXT PRIMARY KEY, context_id TEXT, stakeholder_group TEXT, inclusion_level REAL, idea_influence REAL, burden_visibility REAL, knowledge_recognition REAL, interpretive_trust REAL, power_distance REAL, legitimacy_signal REAL);
CREATE TABLE intervention_library (intervention_id TEXT PRIMARY KEY, intervention_name TEXT, target_bias TEXT, process_cost REAL, implementation_complexity REAL, variation_gain REAL, legitimacy_gain REAL, evidence_gain REAL, political_safety_need REAL, decision_memory_gain REAL);
CREATE TABLE decision_memory (decision_id TEXT PRIMARY KEY, context_id TEXT, idea_id TEXT, frame_id TEXT, assumption_id TEXT, decision_date TEXT, idea_space_summary TEXT, bias_risks_identified TEXT, stakeholder_visibility_review TEXT, intervention_applied TEXT, decision_outcome TEXT, rejected_or_deferred_reason TEXT, revision_trigger TEXT);
CREATE VIEW bias_context_profiles AS SELECT context_id, context_name, ROUND(-0.12*availability_pressure-0.12*anchoring_intensity-0.13*conformity_pressure-0.12*framing_rigidity-0.10*institutional_lock_in-0.08*expert_enclosure-0.07*ai_familiarity_pressure+0.16*stakeholder_diversity+0.18*exploratory_variation+0.12*evidence_discipline+0.08*political_safety+0.08*decision_memory_quality,4) AS bias_adjusted_ideation_profile FROM bias_contexts;
CREATE VIEW premature_convergence_risks AS SELECT context_id, context_name, ROUND(anchoring_intensity*conformity_pressure*framing_rigidity,4) AS premature_convergence_risk, ROUND(institutional_lock_in*(1.0-stakeholder_diversity),4) AS institutional_bias_risk, ROUND(ai_familiarity_pressure*(1.0-exploratory_variation),4) AS ai_familiarity_risk FROM bias_contexts;
CREATE VIEW idea_space_diversity_scores AS SELECT idea_id, context_id, idea_name, ROUND(0.14*stakeholder_visibility+0.14*novelty_level+0.14*evidence_pathway+0.14*strategic_relevance+0.10*implementation_pathway+0.14*source_diversity-0.10*social_safety-0.10*assumption_burden,4) AS idea_space_diversity_score FROM idea_space_inventory;
CREATE VIEW frame_rotation_scores AS SELECT frame_id, context_id, frame_name, ROUND(0.10*MIN(1.0,idea_count/12.0)+0.18*MIN(1.0,distinct_mechanisms/8.0)+0.16*stakeholder_inclusion+0.16*system_level_coverage+0.14*evidence_pathway_quality-0.08*comfort_level+0.18*frame_shift_value,4) AS frame_rotation_score FROM frame_rotation;
CREATE VIEW assumption_challenge_priorities AS SELECT assumption_id, context_id, assumption_text, ROUND(0.22*strategic_importance+0.22*challenge_potential+0.18*(1.0-evidence_strength)+0.16*power_protection_risk+0.12*(1.0-stakeholder_burden_visibility),4) AS challenge_priority FROM assumption_register;
CREATE VIEW stakeholder_visibility_scores AS SELECT review_id, context_id, stakeholder_group, ROUND(0.16*inclusion_level+0.18*idea_influence+0.16*burden_visibility+0.16*knowledge_recognition+0.12*interpretive_trust-0.12*power_distance+0.14*legitimacy_signal,4) AS stakeholder_visibility_score FROM stakeholder_visibility;
CREATE VIEW intervention_value_scores AS SELECT intervention_id, intervention_name, target_bias, ROUND(0.20*variation_gain+0.16*legitimacy_gain+0.16*evidence_gain+0.16*decision_memory_gain-0.12*process_cost-0.10*implementation_complexity-0.10*political_safety_need,4) AS intervention_value_score FROM intervention_library;
